import {api,el,loadAssets,statusLabels,statusIcons} from './display-api.mjs';
export function createPicker(context){
 const dialog=el('dialog',undefined,'display-dialog piece-picker');dialog.innerHTML='<button class="dialog-close" aria-label="Close piece selector">×</button><h2>Add pieces</h2><p class="hint">Every status can appear on every display. Reusing a collection copy does not change your level.</p><div class="picker-tabs"><button data-source="collection" aria-pressed="true">My collection</button><button data-source="catalogue" aria-pressed="false">Full catalogue</button></div><label>Search pieces<input type="search" placeholder="Name or animal"></label><label class="status-filter">Status<select><option value="all">All statuses</option><option value="current">Currently owned</option><option value="previous">Previously owned</option><option value="wishlist">Wishlist</option></select></label><div class="bulk-actions"><button data-status="current">+ All owned</button><button data-status="previous">+ All previously owned</button><button data-status="wishlist">+ All wishlist</button></div><label class="new-copy-status" hidden>Add new copy as<select><option value="wishlist">Wishlist</option><option value="current">Currently owned</option><option value="previous">Previously owned</option></select></label><p class="picker-status" role="status"></p><div class="picker-results"></div>';
 document.body.append(dialog);let source='collection',busy=false,catalog,assets;
 const results=dialog.querySelector('.picker-results'),message=dialog.querySelector('.picker-status');
 dialog.querySelector('.dialog-close').onclick=()=>{if(!busy)dialog.close()};dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault()});
 async function mutate(body){if(busy)return;busy=true;dialog.querySelectorAll('button').forEach(b=>b.disabled=true);message.textContent='Adding…';try{await context.beforeMutate();const state=context.getState(),next=await api('displays',{method:'POST',body:JSON.stringify({...body,displayId:state.layoutId,revision:state.revision})});const added=next.order.find(id=>!state.order.includes(id));context.applyState(next);dialog.close();if(added)context.focusPiece?.(added)}catch(e){message.textContent=e.message}finally{busy=false;dialog.querySelectorAll('button').forEach(b=>b.disabled=false)}}
 function render(){if(!catalog)return;results.replaceChildren();const state=context.getState(),q=dialog.querySelector('input').value.toLowerCase(),filter=dialog.querySelector('.status-filter select').value;
 const values=source==='collection'?state.items.filter(i=>filter==='all'||i.status===filter):[...catalog.values()].map(p=>({productId:p.id}));
 let count=0;for(const i of values){const p=catalog.get(i.productId);if(!p||!p.name.toLowerCase().includes(q))continue;count++;const row=el('article',undefined,'picker-row'),img=new Image();img.loading='lazy';img.alt='';img.src=assets[p.id]?.src||p.img;const text=el('div');text.append(el('strong',p.name));if(i.status)text.append(el('small',statusIcons[i.status]+' '+statusLabels[i.status]+' · Copy '+i.id.slice(0,6)));else text.append(el('small','Creates a new collection entry'));
 const button=el('button',source==='collection'?(state.order.includes(i.id)?'On display':'Place copy'):'Add new copy');button.disabled=busy||state.order.includes(i.id);button.onclick=()=>mutate(source==='collection'?{action:'addItems',itemIds:[i.id]}:{action:'addProduct',productId:i.productId,status:dialog.querySelector('.new-copy-status select').value});row.append(img,text,button);results.append(row)}if(!count)results.append(el('p',source==='collection'?'No matching copies. Try the full catalogue.':'No matching pieces.'));
 }
 for(const button of dialog.querySelectorAll('[data-source]'))button.onclick=()=>{source=button.dataset.source;for(const b of dialog.querySelectorAll('[data-source]'))b.setAttribute('aria-pressed',String(b===button));dialog.querySelector('.status-filter').hidden=source!=='collection';dialog.querySelector('.bulk-actions').hidden=source!=='collection';dialog.querySelector('.new-copy-status').hidden=source!=='catalogue';render()};
 dialog.querySelector('input').oninput=render;dialog.querySelector('.status-filter select').onchange=render;
 for(const b of dialog.querySelectorAll('[data-status]'))b.onclick=()=>mutate({action:'addStatus',status:b.dataset.status});
 return {open:async()=>{dialog.showModal();message.textContent='Loading pieces…';try{({catalog,assets}=await loadAssets());message.textContent='';render()}catch(e){message.textContent=e.message}}};
}
export function setupRename(context){const button=document.querySelector('#renameDisplay');button.hidden=false;const dialog=el('dialog',undefined,'display-dialog');dialog.innerHTML='<form><button type="button" class="dialog-close" aria-label="Close rename">×</button><h2>Rename display</h2><label>Name<input name="name" required maxlength="60"></label><p role="status"></p><button type="submit" class="edge-button">Save name</button></form>';document.body.append(dialog);const form=dialog.querySelector('form');button.onclick=()=>{form.elements.name.value=context.getState().name;dialog.showModal()};dialog.querySelector('.dialog-close').onclick=()=>dialog.close();form.onsubmit=async e=>{e.preventDefault();const submit=form.querySelector('[type=submit]');submit.disabled=true;try{await context.beforeMutate();const state=context.getState();context.applyState(await api('displays',{method:'POST',body:JSON.stringify({action:'rename',displayId:state.layoutId,revision:state.revision,name:form.elements.name.value})}));dialog.close()}catch(e){form.querySelector('[role=status]').textContent=e.message}finally{submit.disabled=false}}}
